func testAccBigtableMemoryLayer_bigtableMemoryLayerExample(context map[string]interface{}) string {
	return acctest.Nprintf(`
resource "google_bigtable_instance" "instance" {
  name          = "%{instance_name}"
  instance_type = "PRODUCTION"
  edition       = "ENTERPRISE_PLUS"
  cluster {
    cluster_id   = "%{cluster_id}"
    zone         = "us-central1-b"
    num_nodes    = 1
    storage_type = "SSD"
  }

  deletion_protection = false
}

resource "google_bigtable_memory_layer" "memory_layer" {
  instance = google_bigtable_instance.instance.name
  cluster  = google_bigtable_instance.instance.cluster[0].cluster_id
}

resource "google_bigtable_app_profile" "ap" {
  instance       = google_bigtable_instance.instance.name
  app_profile_id = "%{app_profile_name}"

  single_cluster_routing {
    cluster_id                 = google_bigtable_memory_layer.memory_layer.cluster
    allow_transactional_writes = true
  }

  standard_isolation {
    priority = "PRIORITY_LOW"
    memory_config {}
  }

  ignore_warnings = true
}
`, context)
}

func testAccCheckBigtableMemoryLayerDestroyProducer(t *testing.T) func(s *terraform.State) error {
	return func(s *terraform.State) error {
		for name, rs := range s.RootModule().Resources {
			if rs.Type != "google_bigtable_memory_layer" {
				continue
			}
			if strings.HasPrefix(name, "data.") {
				continue
			}

			config := acctest.GoogleProviderConfig(t)

			url, err := tpgresource.ReplaceVarsForTest(config, rs, transport_tpg.BaseUrl(bigtable.Product, config)+"projects/{{project}}/instances/{{instance}}/clusters/{{cluster}}/memoryLayer")
			if err != nil {
				return err
			}

			billingProject := ""

			if config.BillingProject != "" {
				billingProject = config.BillingProject
			}

			res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   billingProject,
				RawURL:    url,
				UserAgent: config.UserAgent,
			})
			if err != nil {
				continue
			}

			if v, ok := res["state"]; ok && v != "DISABLED" {
				return fmt.Errorf("BigtableMemoryLayer still enabled at %s (state=%v)", url, v)
			}
		}

		return nil
	}
}
